 void BuildDownloadLimit(Panel body,MonitorConfig cfg){SettingDescription(body,"限制本机所有非回环 TCP/UDP 入站数据的平均接收速率，浏览器、下载器及视频等共享一个上限。使用 WinDivert 签名驱动；首次启用时由系统 PowerShell 校验组件并复制到 Program Files 受保护目录，需要管理员授权。不会自动启动，退出桌宠会停止。它在本机接收后整形，短时峰值、协议重传和 VPN 虚拟网卡可能使物理网卡读数不同，不能保证路由器侧瞬时流量严格不超过数值。尚未进行整机限速实测，首次使用前请保存正在下载的任务。");var rate=TaskbarInput(body,"下载上限（MiB/s）",cfg.DownloadLimitMiB.ToString(System.Globalization.CultureInfo.InvariantCulture),100);limitStatus=Text(assistant.Limiter.Status,13);body.Children.Add(limitStatus);Button(body,"保存限速数值",()=>{double v=TaskbarNumber(rate);if(Double.IsNaN(v)||Double.IsInfinity(v)||v<.1||v>10000)throw new ArgumentException("下载上限0.1–10000 MiB/s。");SaveMonitor(()=>cfg.DownloadLimitMiB=v);});Button(body,"启用整机下载限速（管理员授权）",()=>{if(System.Windows.MessageBox.Show(this,"将使用系统 PowerShell 校验组件，在 Program Files 创建受保护副本后加载 WinDivert 签名驱动，对整机入站 TCP/UDP 数据实施平均限速，可能影响 VPN、视频与下载。可随时停止；退出桌宠也会停止。是否继续？","启用下载限速",System.Windows.MessageBoxButton.YesNo,System.Windows.MessageBoxImage.Question)!=System.Windows.MessageBoxResult.Yes)return;double v=TaskbarNumber(rate);assistant.Limiter.Start(home,v);SaveMonitor(()=>cfg.DownloadLimitMiB=v);limitStatus.Text=assistant.Limiter.Status;});Button(body,"停止限速 · 恢复正常速度",()=>{assistant.Limiter.Dispose();limitStatus.Text=assistant.Limiter.Status;});}

 void BuildQuotaSettings(Panel body,MonitorConfig cfg){var q=cfg.Quota??(cfg.Quota=new CodexQuotaConfig());MonitorToggle(body,"监测 Codex 五小时和周额度",()=>q.Enabled,v=>q.Enabled=v);SettingDescription(body,"先确认本机额度程序与数据目录，再通过已登录的 Codex 官方 app-server 每60秒查询，不读取或保存登录令牌，不消耗对话额度。任务栏显示的是剩余百分比；超过5分钟未核验则显示—；未启动周期显示“待启动”，已过期且未确认的旧窗口显示“待核验”。额度报警配合警觉动作与已核实原声，并遵守总音量和全屏静音。");quotaStatus=Text("",12);body.Children.Add(quotaStatus);quotaCountdown=Text("",15);body.Children.Add(quotaCountdown);Button(body,"额度与重置提醒设置 →",()=>{memoTab="额度与重置";ShowPage("侦探备忘录");});var connection=body;var executable=TaskbarInput(connection,"Codex.exe（留空自动找）",q.Executable,280);Button(connection,"选择 Codex.exe…",()=>{using(var picker=new System.Windows.Forms.OpenFileDialog{Filter="Codex程序|codex.exe|可执行文件|*.exe"})if(picker.ShowDialog()==System.Windows.Forms.DialogResult.OK)executable.Text=picker.FileName;});var codexHome=TaskbarInput(connection,"Codex数据目录",q.Home,280);Button(connection,"选择 Codex 数据目录…",()=>{using(var picker=new System.Windows.Forms.FolderBrowserDialog{Description="选择含 Codex 配置的 CODEX_HOME 目录；无需打开或复制 auth.json"})if(picker.ShowDialog()==System.Windows.Forms.DialogResult.OK)codexHome.Text=picker.SelectedPath;});SettingDescription(connection,"若独立启动后提示未登录，请选择与你当前 Codex 相同的数据目录；默认沿用启动环境的 CODEX_HOME。目录仅保存路径，不复制其中内容。");SettingDescription(body,"倒计时基于官方返回的预计重置时间，每秒更新；开启后台查询时每60秒查询额度。周额度提前回升会单独记录为疑似重置/调整。记录首次检测时间和前次核验时间，无法保证官方实际重置的精确时刻。账号无法识别或切换时不推断重置，历史最多100条，保存在用户数据中。");quotaHistory=Text("",12);var history=new Expander{Header="重置记录 · 最近8条",Content=quotaHistory,Margin=new System.Windows.Thickness(0,8,0,8)};body.Children.Add(history);var buttons=new WrapPanel{Margin=new System.Windows.Thickness(0,10,0,0)};body.Children.Add(buttons);Button(buttons,"保存额度连接设置",()=>{if(!String.IsNullOrWhiteSpace(executable.Text))CodexQuotaReader.FindExecutable(executable.Text);if(!String.IsNullOrWhiteSpace(codexHome.Text)&&!System.IO.Directory.Exists(codexHome.Text))throw new ArgumentException("Codex数据目录不存在。");SaveMonitor(()=>{q.Home=codexHome.Text.Trim();q.Executable=executable.Text.Trim();});assistant.QuotaReader.RefreshNow();});Button(buttons,"将两项额度加入任务栏",()=>{SaveMonitor(()=>{foreach(string key in new[]{"codex5h","codex7d"})if(!cfg.TaskbarItems.Contains(key))cfg.TaskbarItems.Add(key);});taskbarDraft=null;ShowPage("任务栏外观");});Button(buttons,"导出重置记录…",()=>{using(var picker=new System.Windows.Forms.SaveFileDialog{Filter="重置报告|*.txt",FileName="Codex额度重置记录.txt"})if(picker.ShowDialog()==System.Windows.Forms.DialogResult.OK){string report;lock(assistant)report=String.Join("\r\n\r\n",(q.ResetHistory??new System.Collections.Generic.List<CodexQuotaReset>()).Select(x=>x.Report()));System.IO.File.WriteAllText(picker.FileName,"记录时间是首次检测时刻，非官方实际执行时刻。\r\n\r\n"+report,new System.Text.UTF8Encoding(true));}});Button(buttons,"授权并连接额度服务…",()=>{var identity=assistant.QuotaReader.Trust.Inspect(executable.Text.Trim(),codexHome.Text.Trim());if(System.Windows.MessageBox.Show(this,"将允许后台启动以下程序读取额度。请确认来源可信。\n\n程序："+identity.Executable+"\n数据目录："+identity.Home+"\nSHA-256："+identity.Sha256+"\n\n授权只对当前Windows账户和本机有效，会加密保存在本地数据目录。相同程序无需每次确认；程序更新或路径改变后需重新确认。", "授权额度程序",System.Windows.MessageBoxButton.YesNo,System.Windows.MessageBoxImage.Question)!=System.Windows.MessageBoxResult.Yes)return;assistant.QuotaReader.Trust.Approve(identity);SaveMonitor(()=>{q.Executable=identity.Executable;q.Home=identity.Home;q.Enabled=true;});executable.Text=q.Executable;codexHome.Text=q.Home;assistant.QuotaReader.RefreshNow();quotaStatus.Text="已授权，下次采样将核验程序内容后读取额度。";});Button(buttons,"撤销额度程序授权",()=>{assistant.QuotaReader.Trust.Revoke();SaveMonitor(()=>q.Enabled=false);});Button(buttons,"立即刷新额度",()=>{assistant.QuotaReader.RefreshNow();quotaStatus.Text="已请求重新核验，稍后显示结果。";});}
 void BuildWakeSettings(Panel body,CodexQuotaConfig q){
  var wake=q.Wake??(q.Wake=new CodexWakeConfig());SettingsLabel(body,"最小请求自动唤醒 · 可选");MonitorToggle(body,"额度恢复后自动发送一次最小请求（消耗少量额度）",()=>wake.Enabled,v=>{wake.Enabled=v;if(!v)wake.CandidateKeys.Clear();});MonitorToggle(body,"周额度恢复时尝试",()=>wake.Weekly,v=>wake.Weekly=v);MonitorToggle(body,"五小时额度恢复时也尝试",()=>wake.FiveHour,v=>wake.FiveHour=v);wakeStatus=Text(wake.LastResult,12);body.Children.Add(wakeStatus);SettingDescription(body,"默认关闭，默认只针对周额度。开启后需桌宠运行、后台查询开启且额度程序已授权；两次官方查询确认恢复、账户一致后，本周期只尝试一次，失败不循环。只选官方模型列表中支持低推理的mini/luna模型，无可用模型则跳过，不回退高成本模型。请求使用空目录、临时会话并关闭工具和项目指令，不携带当前聊天；仍有系统提示开销，不能保证固定几个token。不会购买或兑换重置券。电脑关机、休眠期间无法发送请求；恢复后核验。");
 }
 DatePicker SubscriptionDate(Panel row,string name,DateTime? value){var date=new DatePicker{SelectedDate=value,Width=220,Height=46,FontSize=15,Margin=new System.Windows.Thickness(0,4,16,8),Background=TerminalStyle.BrushOf("#0D1526"),Foreground=TerminalStyle.Text};date.Template=(System.Windows.Controls.ControlTemplate)System.Windows.Markup.XamlReader.Parse(@"<ControlTemplate xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation' xmlns:x='http://schemas.microsoft.com/winfx/2006/xaml' TargetType='DatePicker'><Grid x:Name='PART_Root'><Border CornerRadius='10' Background='{TemplateBinding Background}' BorderBrush='#34445F' BorderThickness='1'><Grid><Grid.ColumnDefinitions><ColumnDefinition/><ColumnDefinition Width='42'/></Grid.ColumnDefinitions><DatePickerTextBox x:Name='PART_TextBox' Background='Transparent' BorderThickness='0' Foreground='{TemplateBinding Foreground}' FontSize='15' VerticalContentAlignment='Center' Padding='0'><DatePickerTextBox.Template><ControlTemplate TargetType='DatePickerTextBox'><ScrollViewer x:Name='PART_ContentHost' Margin='12,0' VerticalAlignment='Center'/></ControlTemplate></DatePickerTextBox.Template></DatePickerTextBox><Button x:Name='PART_Button' Grid.Column='1' Margin='3,6,7,6' ToolTip='打开日历选择日期'><Button.Template><ControlTemplate TargetType='Button'><Border CornerRadius='7' Background='#24364F'><Path Width='17' Height='17' Stretch='Uniform' Stroke='#A6C9FF' StrokeThickness='1.4' Data='M2,4 L18,4 L18,18 L2,18 Z M2,8 L18,8 M6,1 L6,6 M14,1 L14,6 M6,11 L8,11 M12,11 L14,11 M6,14 L8,14 M12,14 L14,14'/></Border></ControlTemplate></Button.Template></Button></Grid></Border><Popup x:Name='PART_Popup' Placement='Bottom' PlacementTarget='{Binding RelativeSource={RelativeSource TemplatedParent}}' StaysOpen='False' AllowsTransparency='True'/></Grid></ControlTemplate>");row.Children.Add(date);System.Windows.Automation.AutomationProperties.SetName(date,name);return date;}
 TextBox SubscriptionClock(Panel row,string name,string value){var field=new StackPanel{Margin=new System.Windows.Thickness(0,0,16,8)};row.Children.Add(field);field.Children.Add(Text(name,12));var controls=new StackPanel{Orientation=Orientation.Horizontal};field.Children.Add(controls);var box=TaskbarName(new TextBox{Text=value,Width=94,Height=46,FontSize=17,TextAlignment=System.Windows.TextAlignment.Center,VerticalContentAlignment=System.Windows.VerticalAlignment.Center,MaxLength=5,ToolTip="可输入HH:mm；选中小时或分钟后，用上下键或滚轮调节。"},name);box.Template=(ControlTemplate)System.Windows.Markup.XamlReader.Parse(@"<ControlTemplate xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation' xmlns:x='http://schemas.microsoft.com/winfx/2006/xaml' TargetType='TextBox'><Border x:Name='InputBorder' CornerRadius='10' Background='{TemplateBinding Background}' BorderBrush='#34445F' BorderThickness='1'><ScrollViewer x:Name='PART_ContentHost' Margin='10,0' VerticalAlignment='Center'/></Border><ControlTemplate.Triggers><Trigger Property='IsKeyboardFocused' Value='True'><Setter TargetName='InputBorder' Property='BorderBrush' Value='#9BB9FF'/></Trigger></ControlTemplate.Triggers></ControlTemplate>");controls.Children.Add(box);Action<int> change=delta=>{if(box.IsReadOnly)return;TimeSpan clock;if(!TimeSpan.TryParseExact(box.Text,@"hh\:mm",System.Globalization.CultureInfo.InvariantCulture,out clock))clock=TimeSpan.Zero;int start=box.SelectionStart>=3?3:0;int minutes=((int)clock.TotalMinutes+(start==0?60:1)*delta+1440)%1440;box.Text=(minutes/60).ToString("D2")+":"+(minutes%60).ToString("D2");box.Focus();box.Select(start,2);};var arrows=new StackPanel();controls.Children.Add(arrows);foreach(int direction in new[]{1,-1}){int step=direction;var button=Button(arrows,direction==1?"▴":"▾",()=>change(step));button.Width=30;button.Height=22;button.MinHeight=20;button.Padding=new System.Windows.Thickness(3,0,3,0);button.Margin=new System.Windows.Thickness(5,0,0,2);button.ToolTip=direction==1?"增加选中的小时或分钟":"减少选中的小时或分钟";}box.PreviewKeyDown+=(sender,e)=>{if(e.Key==System.Windows.Input.Key.Up||e.Key==System.Windows.Input.Key.Down){change(e.Key==System.Windows.Input.Key.Up?1:-1);e.Handled=true;}};box.PreviewMouseWheel+=(sender,e)=>{if(box.IsKeyboardFocusWithin){change(e.Delta>0?1:-1);e.Handled=true;}};return box;}
 static DateTime SubscriptionDateTime(DatePicker date,TextBox time,string label){if(!date.SelectedDate.HasValue)throw new ArgumentException("请选择"+label+"日期。");TimeSpan clock;if(!TimeSpan.TryParseExact(time.Text.Trim(),@"hh\:mm",System.Globalization.CultureInfo.InvariantCulture,out clock)||clock.TotalHours>=24)throw new ArgumentException(label+"时间请输入00:00–23:59。");return date.SelectedDate.Value.Date.Add(clock);}
 void BuildSubscriptionSettings(Panel body,CodexQuotaConfig q){
  var sub=q.Subscription??(q.Subscription=new CodexSubscriptionConfig());SettingsLabel(body,"套餐到期 · 本机备忘");MonitorToggle(body,"启用套餐到期提醒",()=>sub.Enabled,v=>sub.Enabled=v);subscriptionStatus=Text(sub.Status(DateTime.Now),13);body.Children.Add(subscriptionStatus);
  var mode=TaskbarChoice(body,"到期时间填写方式",new[]{"填写订阅时间，自动计算到期日","直接填写到期时间"},sub.FromSubscription||!sub.Deadline().HasValue?0:1);mode.Width=310;
  var purchase=new StackPanel();var purchaseFrame=new System.Windows.Controls.Border{Child=purchase,CornerRadius=new System.Windows.CornerRadius(12),Padding=new System.Windows.Thickness(16),Margin=new System.Windows.Thickness(0,8,0,12),BorderThickness=new System.Windows.Thickness(1)};purchaseFrame.SetResourceReference(System.Windows.Controls.Border.BackgroundProperty,"DeskBase");purchaseFrame.SetResourceReference(System.Windows.Controls.Border.BorderBrushProperty,"DeskLine");body.Children.Add(purchaseFrame);purchase.Children.Add(Text("01  本次订阅或续费时间",15));var purchaseRow=new WrapPanel();purchase.Children.Add(purchaseRow);var subscribed=SubscriptionDate(purchaseRow,"套餐订阅日期",sub.Start().HasValue?(DateTime?)sub.Start().Value.Date:null);var subscribedTime=SubscriptionClock(purchaseRow,"订阅时间（24小时）",sub.Start().HasValue?sub.Start().Value.ToString("HH:mm"):"00:00");var period=TaskbarChoice(purchase,"订阅周期",new[]{"按日历月 · 1个月","固定时长 · 30天","自定义天数","按日历月 · 12个月"},sub.DurationMode=="days"?(sub.SubscriptionDays==30?1:2):sub.SubscriptionMonths==12?3:0);period.Width=250;var customDays=TaskbarInput(purchase,"订阅天数",sub.SubscriptionDays.ToString(),90);var dayRow=(System.Windows.UIElement)customDays.Parent;
  body.Children.Add(Text("预计到期日期与时间",14));var row=new WrapPanel();body.Children.Add(row);var date=SubscriptionDate(row,"套餐到期日期",sub.Deadline().HasValue?(DateTime?)sub.Deadline().Value.Date:null);var time=SubscriptionClock(row,"到期时间（24小时）",sub.Deadline().HasValue?sub.Deadline().Value.ToString("HH:mm"):"23:59");var preview=Text("",17);var resultFrame=new System.Windows.Controls.Border{Child=preview,CornerRadius=new System.Windows.CornerRadius(12),Padding=new System.Windows.Thickness(16),Margin=new System.Windows.Thickness(0,6,0,12),BorderThickness=new System.Windows.Thickness(2,0,0,0)};resultFrame.SetResourceReference(System.Windows.Controls.Border.BorderBrushProperty,"DeskAccent");resultFrame.SetResourceReference(System.Windows.Controls.Border.BackgroundProperty,"DeskBase");body.Children.Add(resultFrame);
  Action update=()=>{bool calculate=mode.SelectedIndex==0;purchaseFrame.Visibility=calculate?System.Windows.Visibility.Visible:System.Windows.Visibility.Collapsed;row.Visibility=calculate?System.Windows.Visibility.Collapsed:System.Windows.Visibility.Visible;date.IsEnabled=!calculate;time.IsReadOnly=calculate;dayRow.Visibility=period.SelectedIndex==2?System.Windows.Visibility.Visible:System.Windows.Visibility.Collapsed;if(!calculate){preview.Text="直接填写已知的到期时间。";return;}try{var begin=SubscriptionDateTime(subscribed,subscribedTime,"订阅");int count=period.SelectedIndex==1?30:period.SelectedIndex==2?TaskbarInt(customDays):period.SelectedIndex==3?12:1;if(count<1||count>3660)throw new ArgumentException("订阅天数为1–3660。");var expected=period.SelectedIndex==1||period.SelectedIndex==2?begin.AddDays(count):begin.AddMonths(count);date.SelectedDate=expected.Date;time.Text=expected.ToString("HH:mm");preview.Text="自动计算："+begin.ToString("yyyy-MM-dd HH:mm")+" ＋ "+(period.SelectedIndex==1||period.SelectedIndex==2?count+"天":count+"个月")+" → "+expected.ToString("yyyy-MM-dd HH:mm");}catch(ArgumentException){date.SelectedDate=null;time.Text="";preview.Text="填写订阅日期和时间后，自动显示预计到期时间。";}};
  mode.SelectionChanged+=(s,e)=>update();subscribed.SelectedDateChanged+=(s,e)=>update();subscribedTime.TextChanged+=(s,e)=>update();period.SelectionChanged+=(s,e)=>update();customDays.TextChanged+=(s,e)=>update();update();
  Button(body,"打开官方账户设置核对到期日",()=>System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo("https://chatgpt.com/#settings"){UseShellExecute=true}));var days=MemoPoints(body,"提前提醒（天；0表示到期当天）",(sub.ReminderDays??new System.Collections.Generic.List<int>{1,3,7}).Select(x=>(double)x),0,365,"0, 1, 3, 7",30);SettingDescription(body,"官方自助月付按每月订阅日期续费，并非固定30天。按日历月时，月底不足对应日期取当月最后一天；固定30天或自定义天数则按实际天数相加。请按实际订单选择。时间使用本机时区，记不清时分可保留00:00。计算结果是预计到期日，实际以订阅账单为准，不会自动假定已续费或逐月延后。所有日期与提醒记录仅保存在本机用户数据区；提醒开关与多个提前天数继续生效。");
  Button(body,"保存套餐到期提醒",()=>{bool calculate=mode.SelectedIndex==0;DateTime? begin=calculate?(DateTime?)SubscriptionDateTime(subscribed,subscribedTime,"订阅"):null;bool dayBased=calculate&&(period.SelectedIndex==1||period.SelectedIndex==2);int count=!calculate?1:period.SelectedIndex==1?30:period.SelectedIndex==2?TaskbarInt(customDays):period.SelectedIndex==3?12:1;if(count<1||count>3660)throw new ArgumentException("订阅天数为1–3660。");DateTime expiry=begin.HasValue?(dayBased?begin.Value.AddDays(count):begin.Value.AddMonths(count)):SubscriptionDateTime(date,time,"到期");var points=CodexSubscriptionConfig.ParseDays(days.Text);SaveMonitor(()=>{sub.FromSubscription=calculate;if(begin.HasValue)sub.SubscribedLocal=begin.Value.ToString("yyyy-MM-dd'T'HH:mm");if(calculate){sub.DurationMode=dayBased?"days":"months";if(dayBased)sub.SubscriptionDays=count;else sub.SubscriptionMonths=count;}sub.ExpiresLocal=expiry.ToString("yyyy-MM-dd'T'HH:mm");sub.ReminderDays=points;});subscriptionStatus.Text=sub.Status(DateTime.Now);});
 }
 void BuildExitConnection(Panel body,MonitorConfig cfg){SettingDescription(body,"出口查询仅使用已授权的 ipwho.is。系统代理适用于 FlClash 系统代理模式；TUN 模式可直连。不会在代理失败时偷偷改用直连，避免将其他出口误判为 VPN 正常。");var mode=TaskbarChoice(body,"出口查询通道",new[]{"跟随 Windows 系统代理","直连（适用于 TUN）","手动 HTTP 代理"},cfg.ExitProxyMode=="direct"?1:cfg.ExitProxyMode=="manual"?2:0);var address=TaskbarInput(body,"HTTP代理地址",cfg.ExitProxyAddress,290);Button(body,"保存出口连接方式",()=>{string selected=new[]{"system","direct","manual"}[Math.Max(0,mode.SelectedIndex)];NetworkExit.Proxy(selected,address.Text.Trim());SaveMonitor(()=>{cfg.ExitProxyMode=selected;cfg.ExitProxyAddress=address.Text.Trim();});});}
